<?php
$title='Logs y diagnóstico';require __DIR__.'/partials/top.php';$pdo=appDb();$tid=(int)$_SESSION['user']['tenant_id'];$level=strtolower((string)($_GET['level']??'all'));$module=trim((string)($_GET['module']??''));$rows=[];$counts=['info'=>0,'warning'=>0,'error'=>0];$modules=[];
try{$q=$pdo->prepare("SELECT level,COUNT(*) n FROM system_event_logs WHERE tenant_id=? GROUP BY level");$q->execute([$tid]);foreach($q->fetchAll() as $r)$counts[$r['level']]=(int)$r['n'];$q=$pdo->prepare("SELECT DISTINCT module FROM system_event_logs WHERE tenant_id=? ORDER BY module");$q->execute([$tid]);$modules=$q->fetchAll(PDO::FETCH_COLUMN);$sql='SELECT * FROM system_event_logs WHERE tenant_id=?';$params=[$tid];if(in_array($level,['info','warning','error'],true)){$sql.=' AND level=?';$params[]=$level;}if($module!==''){$sql.=' AND module=?';$params[]=$module;}$sql.=' ORDER BY id DESC LIMIT 400';$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();}catch(Throwable $e){}
?>
<section class="welcome"><div><small>OBSERVABILIDAD</small><h1>Logs y diagnóstico</h1><p>Eventos administrativos y técnicos en un solo lugar, sin llenar la consola del navegador.</p></div><a class="secondary-action" href="?page=settings#server-health"><i class="fa-solid fa-heart-pulse"></i> Salud del sistema</a></section>
<section class="premium-kpis logs-kpis"><article><span class="kpi-icon"><i class="fa-solid fa-circle-info"></i></span><div><b><?=number_format($counts['info'])?></b><small>Información</small></div></article><article><span class="kpi-icon"><i class="fa-solid fa-triangle-exclamation"></i></span><div><b><?=number_format($counts['warning'])?></b><small>Advertencias</small></div></article><article><span class="kpi-icon"><i class="fa-solid fa-circle-xmark"></i></span><div><b><?=number_format($counts['error'])?></b><small>Errores</small></div></article><article><span class="kpi-icon"><i class="fa-solid fa-shield-halved"></i></span><div><b>Silenciosa</b><small>Consola pública</small></div></article></section>
<section class="panel spaced"><div class="panel-head premium-card-head"><span class="premium-card-head-icon"><i class="fa-solid fa-list-check"></i></span><div><b>Registro central</b><small>Filtra por severidad y módulo. Los datos sensibles no se registran.</small></div></div><form class="log-filters" method="get"><input type="hidden" name="page" value="logs"><div class="field"><label>Nivel</label><select class="select2" name="level"><option value="all">Todos</option><?php foreach(['info'=>'Información','warning'=>'Advertencia','error'=>'Error'] as $v=>$l):?><option value="<?=$v?>" <?=$level===$v?'selected':''?>><?=$l?></option><?php endforeach?></select></div><div class="field"><label>Módulo</label><select class="select2" name="module"><option value="">Todos</option><?php foreach($modules as $m):?><option value="<?=htmlspecialchars($m)?>" <?=$module===$m?'selected':''?>><?=htmlspecialchars($m)?></option><?php endforeach?></select></div><button class="primary"><i class="fa-solid fa-filter"></i> Aplicar</button><a class="soft" href="?page=logs"><i class="fa-solid fa-rotate-left"></i> Restablecer</a></form><div class="system-log-list"><?php if(!$rows):?><div class="empty-compact"><i class="fa-solid fa-list-check"></i><b>Sin eventos para estos filtros</b><span>Los eventos nuevos aparecerán aquí.</span></div><?php else:foreach($rows as $r):?><article class="system-log-row level-<?=htmlspecialchars($r['level'])?>"><span class="log-level"><i class="fa-solid <?=$r['level']==='error'?'fa-circle-xmark':($r['level']==='warning'?'fa-triangle-exclamation':'fa-circle-info')?>"></i></span><div><div class="system-log-title"><b><?=htmlspecialchars($r['message'])?></b><span><?=htmlspecialchars($r['module'])?></span></div><small><?=htmlspecialchars($r['created_at'])?><?=!empty($r['user_id'])?' · Usuario #'.(int)$r['user_id']:''?></small><?php if(trim((string)$r['context_json'])!==''):?><details><summary>Detalles técnicos</summary><pre><?=htmlspecialchars($r['context_json'])?></pre></details><?php endif?></div></article><?php endforeach;endif?></div></section>
